"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon, type IconName } from "../icons/icon";
import { Slot, slotChildren } from "../lib/slot";

export type FxEffect =
  | "typewriter"
  | "rocket"
  | "swap"
  | "spark"
  | "circle"
  | "shine"
  | "flip"
  | "expand"
  | "badge"
  | "warp";

export interface FxButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Welke beweging bij hover en focus. */
  effect: FxEffect;
  /**
   * Tweede tekst: wat de typemachine intypt, wat op de achterkant van flip staat,
   * of wat verschijnt als expand openschuift.
   */
  hoverLabel?: string;
  /** Eigen icoon; elk effect heeft er anders een passend standaardicoon. */
  icon?: IconName;
  /** Kleurverloop van de gevulde varianten. */
  tone?: "accent" | "violet" | "sunset";
  size?: "sm" | "md" | "lg";
  /** Rendert het kind in plaats van een <button>, bv. een link. */
  asChild?: boolean;
}

const STANDAARD_ICOON: Partial<Record<FxEffect, IconName>> = {
  rocket: "send",
  swap: "send",
  circle: "chevronRight",
  expand: "sparkles",
  badge: "arrowRight",
};

/** Welke effecten een gevulde knop zijn; de rest is een omlijnde. */
const GEVULD: FxEffect[] = ["rocket", "swap", "shine", "expand"];

/**
 * FxButton — knop met één van tien hover-effecten: typemachine, raket,
 * icoonwissel, vonk, cirkel, glans, omslag, uitschuiven, badge en warp.
 * Allemaal CSS, behalve het typen, en allemaal ook op toetsenbordfocus.
 */
export const FxButton = React.forwardRef<HTMLButtonElement, FxButtonProps>(function FxButton(
  {
    effect,
    hoverLabel,
    icon,
    tone = "accent",
    size = "md",
    asChild,
    className,
    children: kinderen,
    onMouseEnter,
    onMouseLeave,
    onFocus,
    onBlur,
    ...rest
  },
  ref
) {
  const Comp = (asChild ? Slot : "button") as React.ElementType;
  // Met asChild is het label de inhoud van het meegegeven element (bv. de tekst in <a>).
  const slot = slotChildren(asChild, kinderen);
  const children = slot.inner;
  const icoon = icon ?? STANDAARD_ICOON[effect];
  const label = typeof children === "string" ? children : "";

  /* Typemachine: bij hover wordt de tekst gewist en letter voor letter opnieuw getypt. */
  const [getypt, setGetypt] = React.useState<string | null>(null);
  const timer = React.useRef<number | undefined>(undefined);
  React.useEffect(() => () => window.clearInterval(timer.current), []);

  const startTypen = () => {
    if (effect !== "typewriter") return;
    const doel = hoverLabel ?? label;
    window.clearInterval(timer.current);
    let n = 0;
    setGetypt("");
    timer.current = window.setInterval(() => {
      n += 1;
      setGetypt(doel.slice(0, n));
      if (n >= doel.length) window.clearInterval(timer.current);
    }, 70);
  };
  const stopTypen = () => {
    if (effect !== "typewriter") return;
    window.clearInterval(timer.current);
    setGetypt(null);
  };

  const binnen = () => startTypen();
  const buiten = () => stopTypen();

  let inhoud: React.ReactNode;
  switch (effect) {
    case "typewriter":
      inhoud = (
        <span className="lui-fx-label">
          {getypt ?? children}
          {getypt !== null && <span className="lui-fx-caret" aria-hidden="true" />}
        </span>
      );
      break;
    case "rocket":
      inhoud = (
        <>
          <span className="lui-fx-rocketicon" aria-hidden="true">
            {icoon && <Icon name={icoon} size={15} />}
          </span>
          <span className="lui-fx-label">{children}</span>
        </>
      );
      break;
    case "swap":
      inhoud = (
        <>
          <span className="lui-fx-label">{children}</span>
          <span className="lui-fx-swapicon" aria-hidden="true">
            {icoon && <Icon name={icoon} size={17} />}
          </span>
        </>
      );
      break;
    case "circle":
      inhoud = (
        <>
          <span className="lui-fx-blob" aria-hidden="true">
            {icoon && <Icon name={icoon} size={15} />}
          </span>
          <span className="lui-fx-label">{children}</span>
        </>
      );
      break;
    case "flip":
      inhoud = (
        <span className="lui-fx-flipper">
          <span className="lui-fx-face lui-fx-front">{children}</span>
          <span className="lui-fx-face lui-fx-back" aria-hidden="true">
            {hoverLabel ?? children}
          </span>
        </span>
      );
      break;
    case "expand":
      inhoud = (
        <>
          <span className="lui-fx-expandicon" aria-hidden="true">
            {icoon && <Icon name={icoon} size={16} />}
          </span>
          <span className="lui-fx-expandlabel">{hoverLabel ?? children}</span>
        </>
      );
      break;
    case "badge":
      inhoud = (
        <>
          <span className="lui-fx-label">{children}</span>
          <span className="lui-fx-badgedot" aria-hidden="true">
            {icoon && <Icon name={icoon} size={13} />}
          </span>
        </>
      );
      break;
    case "warp":
      inhoud = (
        <span className="lui-fx-label lui-fx-warplabel" data-text={label}>
          {children}
        </span>
      );
      break;
    default:
      inhoud = <span className="lui-fx-label">{children}</span>;
  }

  return (
    <Comp
      ref={ref}
      type={asChild ? undefined : "button"}
      className={cn(
        "lui-fx",
        `lui-fx-${effect}`,
        `lui-fx-${size}`,
        GEVULD.includes(effect) ? "lui-fx-filled" : "lui-fx-outline",
        className
      )}
      data-tone={tone}
      aria-label={effect === "expand" && typeof children === "string" ? children : undefined}
      onMouseEnter={(event: React.MouseEvent<HTMLButtonElement>) => {
        binnen();
        onMouseEnter?.(event);
      }}
      onMouseLeave={(event: React.MouseEvent<HTMLButtonElement>) => {
        buiten();
        onMouseLeave?.(event);
      }}
      onFocus={(event: React.FocusEvent<HTMLButtonElement>) => {
        binnen();
        onFocus?.(event);
      }}
      onBlur={(event: React.FocusEvent<HTMLButtonElement>) => {
        buiten();
        onBlur?.(event);
      }}
      {...rest}
    >
      {slot.wrap(inhoud)}
    </Comp>
  );
});

/* ============================ FxButton ============================ */
.lui-fx {
  --lui-fx-a: var(--accent);
  --lui-fx-b: var(--blue);
  --lui-fx-h: calc(40px * var(--density));
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  height: var(--lui-fx-h); padding: 0 20px; overflow: hidden; isolation: isolate;
  border: 1.5px solid transparent; border-radius: 999px;
  font: inherit; font-size: var(--fs-sm); font-weight: 650; white-space: nowrap;
  cursor: pointer; text-decoration: none;
  transition: transform var(--dur-fast) var(--ease), box-shadow var(--dur) var(--ease),
    color var(--dur) var(--ease), background var(--dur) var(--ease), border-color var(--dur) var(--ease);
}
.lui-fx[data-tone="violet"] { --lui-fx-a: var(--violet); --lui-fx-b: var(--red); }
.lui-fx[data-tone="sunset"] { --lui-fx-a: var(--amber); --lui-fx-b: var(--red); }
.lui-fx-sm { --lui-fx-h: calc(34px * var(--density)); padding: 0 16px; font-size: 13px; }
.lui-fx-lg { --lui-fx-h: calc(48px * var(--density)); padding: 0 26px; font-size: var(--fs-base); }
.lui-fx:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-fx:active { transform: scale(.97); }
.lui-fx:disabled { opacity: .5; cursor: not-allowed; }

.lui-fx-filled {
  background: linear-gradient(120deg, var(--lui-fx-a), var(--lui-fx-b));
  color: #fff;
  box-shadow: 0 6px 18px color-mix(in oklab, var(--lui-fx-a) 32%, transparent);
}
.lui-fx-outline {
  background: var(--surface); color: var(--text);
  border-color: var(--border-strong);
}
.lui-fx-label { position: relative; z-index: 1; display: inline-flex; align-items: center; }

/* 1 · Typemachine: wist en typt opnieuw, met een knipperende cursor. */
.lui-fx-typewriter:is(:hover, :focus-visible) { border-color: var(--lui-fx-a); color: var(--lui-fx-a); }
.lui-fx-caret {
  display: inline-block; width: 2px; height: 1.05em; margin-inline-start: 2px;
  background: currentColor; animation: lui-fx-caret .8s steps(1) infinite;
}
@keyframes lui-fx-caret { 50% { opacity: 0; } }

/* 2 · Raket: het icoon vertrekt naar boven en landt weer onderaan. */
.lui-fx-rocketicon { position: relative; z-index: 1; display: inline-grid; transform: rotate(-45deg); }
.lui-fx-rocket:is(:hover, :focus-visible) { transform: translateY(-2px); }
.lui-fx-rocket:is(:hover, :focus-visible) .lui-fx-rocketicon { animation: lui-fx-launch .9s var(--ease-out) both; }
@keyframes lui-fx-launch {
  0% { transform: translate(0, 0) rotate(-45deg); opacity: 1; }
  40% { transform: translate(10px, -30px) rotate(-45deg); opacity: 0; }
  41% { transform: translate(-8px, 26px) rotate(-45deg); opacity: 0; }
  100% { transform: translate(0, 0) rotate(-45deg); opacity: 1; }
}

/* 3 · Icoonwissel: de tekst schuift weg, het icoon schuift erin. */
.lui-fx-swap .lui-fx-label,
.lui-fx-swap .lui-fx-swapicon { transition: transform var(--dur) var(--ease-out), opacity var(--dur); }
.lui-fx-swapicon {
  position: absolute; inset: 0; z-index: 1; display: grid; place-items: center;
  transform: translateX(-120%); opacity: 0;
}
.lui-fx-swap:is(:hover, :focus-visible) .lui-fx-label { transform: translateX(140%); opacity: 0; }
.lui-fx-swap:is(:hover, :focus-visible) .lui-fx-swapicon { transform: none; opacity: 1; }

/* 4 · Vonk: een lichtje loopt rond de rand. */
.lui-fx-spark::before {
  content: ""; position: absolute; inset: -1.5px; z-index: -2; border-radius: inherit;
  background: conic-gradient(from var(--lui-fx-angle, 0deg), transparent 0 70%, var(--lui-fx-a) 82%, var(--lui-fx-b) 92%, transparent 100%);
  opacity: 0; transition: opacity var(--dur);
}
.lui-fx-spark::after {
  content: ""; position: absolute; inset: 1.5px; z-index: -1; border-radius: inherit; background: var(--surface);
}
.lui-fx-spark:is(:hover, :focus-visible) { border-color: transparent; color: var(--lui-fx-a); }
.lui-fx-spark:is(:hover, :focus-visible)::before { opacity: 1; animation: lui-fx-spin 1.6s linear infinite; }
@property --lui-fx-angle { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@keyframes lui-fx-spin { to { --lui-fx-angle: 360deg; } }

/* 5 · Cirkel: het bolletje links groeit uit tot de hele knop. */
.lui-fx-circle { padding-inline-start: 6px; }
.lui-fx-blob {
  position: relative; z-index: 1; display: grid; place-items: center; flex: none;
  width: calc(var(--lui-fx-h) - 12px); height: calc(var(--lui-fx-h) - 12px);
  border-radius: 50%; color: #fff;
}
.lui-fx-blob::before {
  content: ""; position: absolute; inset: 0; z-index: -1; border-radius: 999px;
  background: linear-gradient(120deg, var(--lui-fx-a), var(--lui-fx-b));
  transition: inset var(--dur-slow) var(--ease-out), border-radius var(--dur-slow);
}
.lui-fx-circle:is(:hover, :focus-visible) { color: #fff; border-color: transparent; }
.lui-fx-circle:is(:hover, :focus-visible) .lui-fx-blob::before { inset: -8px -400px -8px -8px; }
.lui-fx-circle .lui-fx-label { padding-inline-end: 6px; }

/* 6 · Glans: een schuine lichtstreep veegt erover. */
.lui-fx-shine::after {
  content: ""; position: absolute; inset: 0; z-index: 0;
  background: linear-gradient(105deg, transparent 30%, rgba(255, 255, 255, .55) 50%, transparent 70%);
  transform: translateX(-110%);
}
.lui-fx-shine:is(:hover, :focus-visible)::after { animation: lui-fx-sheen .8s var(--ease-out); }
@keyframes lui-fx-sheen { to { transform: translateX(110%); } }

/* 7 · Omslag: de knop kantelt en toont zijn achterkant. */
.lui-fx-flip { padding: 0; border: 0; background: transparent; overflow: visible; perspective: 600px; }
.lui-fx-flipper {
  position: relative; display: grid; transform-style: preserve-3d;
  transition: transform var(--dur-slow) var(--ease-out);
}
.lui-fx-face {
  grid-area: 1 / 1; display: grid; place-items: center;
  height: var(--lui-fx-h); padding: 0 22px; border-radius: 999px; backface-visibility: hidden;
}
.lui-fx-front { background: var(--surface); color: var(--text); border: 1.5px solid var(--border-strong); }
.lui-fx-back {
  background: linear-gradient(120deg, var(--lui-fx-a), var(--lui-fx-b)); color: #fff;
  transform: rotateX(180deg);
}
.lui-fx-flip:is(:hover, :focus-visible) .lui-fx-flipper { transform: rotateX(180deg); }

/* 8 · Uitschuiven: een rond icoontje dat openklapt tot een knop met tekst. */
.lui-fx-expand { width: var(--lui-fx-h); padding: 0; gap: 0; transition: width var(--dur-slow) var(--ease-out), box-shadow var(--dur); }
.lui-fx-expandicon { display: grid; place-items: center; flex: none; width: var(--lui-fx-h); }
.lui-fx-expandlabel {
  max-width: 0; opacity: 0; overflow: hidden;
  transition: max-width var(--dur-slow) var(--ease-out), opacity var(--dur);
}
.lui-fx-expand:is(:hover, :focus-visible) { width: calc(var(--lui-fx-h) + 7ch); padding-inline-end: 16px; }
.lui-fx-expand:is(:hover, :focus-visible) .lui-fx-expandlabel { max-width: 12ch; opacity: 1; }

/* 9 · Badge: het rondje met de pijl groeit tot achter de hele tekst. */
.lui-fx-badge { padding-inline-end: 6px; }
/* De badge staat na de tekst in de DOM; zonder dit schildert zijn vulling eroverheen. */
.lui-fx-badge .lui-fx-label { z-index: 2; }
.lui-fx-badgedot {
  position: relative; z-index: 1; display: grid; place-items: center; flex: none;
  width: calc(var(--lui-fx-h) - 12px); height: calc(var(--lui-fx-h) - 12px);
  border-radius: 50%; color: #fff;
}
.lui-fx-badgedot::before {
  content: ""; position: absolute; inset: 0; z-index: -1; border-radius: 999px;
  background: linear-gradient(120deg, var(--lui-fx-a), var(--lui-fx-b));
  transition: inset var(--dur-slow) var(--ease-out);
}
.lui-fx-badgedot svg { transition: transform var(--dur) var(--ease-out); transform: rotate(-45deg); }
.lui-fx-badge:is(:hover, :focus-visible) { color: #fff; border-color: transparent; }
.lui-fx-badge:is(:hover, :focus-visible) .lui-fx-badgedot::before { inset: -8px -8px -8px -400px; }
.lui-fx-badge:is(:hover, :focus-visible) .lui-fx-badgedot svg { transform: rotate(0); }

/* 10 · Warp: de tekst rekt uit en vervaagt, alsof hij wegflitst. */
.lui-fx-warp:is(:hover, :focus-visible) {
  border-color: var(--lui-fx-a);
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--lui-fx-a) 16%, transparent),
    0 0 26px color-mix(in oklab, var(--lui-fx-b) 30%, transparent);
}
.lui-fx-warp:is(:hover, :focus-visible) .lui-fx-warplabel { animation: lui-fx-warp .9s var(--ease-out) both; }
@keyframes lui-fx-warp {
  0% { transform: none; filter: none; letter-spacing: normal; }
  45% { transform: scaleX(1.6) skewX(-14deg); filter: blur(3px); letter-spacing: .3em; opacity: .15; color: var(--lui-fx-a); }
  55% { transform: scaleX(.4); filter: blur(4px); opacity: 0; }
  100% { transform: none; filter: none; opacity: 1; color: var(--lui-fx-a); }
}

@media (prefers-reduced-motion: reduce) {
  .lui-fx, .lui-fx *, .lui-fx::before, .lui-fx::after { animation: none !important; transition: none !important; }
}
